163	export class PolicyEngine {
164	  private rules: PolicyRule[];
165	  private checkers: SafetyCheckerRule[];
166	  private hookCheckers: HookCheckerRule[];
167	  private readonly defaultDecision: PolicyDecision;
168	  private readonly nonInteractive: boolean;
169	  private readonly disableAlwaysAllow: boolean;
170	  private readonly checkerRunner?: CheckerRunner;
171	  private approvalMode: ApprovalMode;
172	
173	  constructor(config: PolicyEngineConfig = {}, checkerRunner?: CheckerRunner) {
174	    this.rules = (config.rules ?? []).sort(
175	      (a, b) => (b.priority ?? 0) - (a.priority ?? 0),
176	    );
177	    this.checkers = (config.checkers ?? []).sort(
178	      (a, b) => (b.priority ?? 0) - (a.priority ?? 0),
179	    );
180	    this.hookCheckers = (config.hookCheckers ?? []).sort(
181	      (a, b) => (b.priority ?? 0) - (a.priority ?? 0),
182	    );
183	    this.defaultDecision = config.defaultDecision ?? PolicyDecision.ASK_USER;
184	    this.nonInteractive = config.nonInteractive ?? false;
185	    this.disableAlwaysAllow = config.disableAlwaysAllow ?? false;
186	    this.checkerRunner = checkerRunner;
187	    this.approvalMode = config.approvalMode ?? ApprovalMode.DEFAULT;
188	  }
189	
190	  /**
191	   * Update the current approval mode.
192	   */
193	  setApprovalMode(mode: ApprovalMode): void {
194	    this.approvalMode = mode;
195	  }
196	
197	  /**
198	   * Get the current approval mode.
199	   */
200	  getApprovalMode(): ApprovalMode {
201	    return this.approvalMode;
202	  }
203	
204	  private isAlwaysAllowRule(rule: PolicyRule): boolean {
205	    return (
206	      rule.priority !== undefined &&
207	      Math.round((rule.priority % 1) * 1000) === ALWAYS_ALLOW_PRIORITY_FRACTION
208	    );
209	  }
210	
211	  private shouldDowngradeForRedirection(
212	    command: string,
213	    allowRedirection?: boolean,
214	  ): boolean {
215	    return (
216	      !allowRedirection &&
217	      hasRedirection(command) &&
218	      this.approvalMode !== ApprovalMode.AUTO_EDIT &&
219	      this.approvalMode !== ApprovalMode.YOLO
220	    );
221	  }
222	
223	  /**
224	   * Check if a shell command is allowed.
225	   */
226	  private async checkShellCommand(
227	    toolName: string,
228	    command: string | undefined,
229	    ruleDecision: PolicyDecision,
230	    serverName: string | undefined,
231	    dir_path: string | undefined,
232	    allowRedirection?: boolean,
233	    rule?: PolicyRule,
234	    toolAnnotations?: Record<string, unknown>,
235	    subagent?: string,
236	  ): Promise<CheckResult> {
237	    if (!command) {
238	      return {
239	        decision: this.applyNonInteractiveMode(ruleDecision),
240	        rule,
241	      };
242	    }
243	
244	    await initializeShellParsers();
245	    const subCommands = splitCommands(command);
246	
247	    if (subCommands.length === 0) {
