44	/**
45	 * Extracts the server name and tool name from a fully qualified MCP tool name.
46	 * Expected format: `mcp_{server_name}_{tool_name}`
47	 * @param name The fully qualified tool name.
48	 * @returns An object containing the extracted `serverName` and `toolName`, or
49	 *          `undefined` properties if the name doesn't match the expected format.
50	 */
51	export function parseMcpToolName(name: string): {
52	  serverName?: string;
53	  toolName?: string;
54	} {
55	  if (!isMcpToolName(name)) {
56	    return {};
57	  }
58	  // Remove the prefix
59	  const withoutPrefix = name.slice(MCP_TOOL_PREFIX.length);
60	  // The first segment is the server name, the rest is the tool name
61	  // Must be strictly `server_tool` where neither are empty
62	  const match = withoutPrefix.match(/^([^_]+)_(.+)$/);
63	  if (match) {
64	    return {
65	      serverName: match[1],
66	      toolName: match[2],
67	    };
68	  }
69	  return {};
70	}
