72	/**
73	 * Assembles a fully qualified MCP tool name (or wildcard pattern) from its server and tool components.
74	 *
75	 * @param serverName The backend MCP server name (can be '*' for global wildcards).
76	 * @param toolName The name of the tool (can be undefined or '*' for tool-level wildcards).
77	 * @returns The fully qualified name (e.g., `mcp_server_tool`, `mcp_*`, `mcp_server_*`).
78	 */
79	export function formatMcpToolName(
80	  serverName: string,
81	  toolName?: string,
82	): string {
83	  if (serverName === '*' && !toolName) {
84	    return `${MCP_TOOL_PREFIX}*`;
85	  } else if (serverName === '*') {
86	    return `${MCP_TOOL_PREFIX}*_${toolName}`;
87	  } else if (!toolName) {
88	    return `${MCP_TOOL_PREFIX}${serverName}_*`;
89	  } else {
90	    return `${MCP_TOOL_PREFIX}${serverName}_${toolName}`;
91	  }
92	}
