47	/**
48	 * Queries the system PolicyEngine to determine tool allowance.
49	 * @returns The PolicyDecision.
50	 * @throws Error if policy requires ASK_USER but the CLI is non-interactive.
51	 */
52	export async function checkPolicy(
53	  toolCall: ValidatingToolCall,
54	  config: Config,
55	  subagent?: string,
56	): Promise<CheckResult> {
57	  const serverName =
58	    toolCall.tool instanceof DiscoveredMCPTool
59	      ? toolCall.tool.serverName
60	      : undefined;
61	
62	  const toolAnnotations = toolCall.tool.toolAnnotations;
63	
64	  const result = await config
65	    .getPolicyEngine()
66	    .check(
67	      { name: toolCall.request.name, args: toolCall.request.args },
68	      serverName,
69	      toolAnnotations,
70	      subagent,
71	    );
72	
73	  const { decision } = result;
74	
75	  // If the tool call was initiated by the client (e.g. via a slash command),
76	  // we treat it as implicitly confirmed by the user and bypass the
77	  // confirmation prompt if the policy engine's decision is 'ASK_USER'.
78	  if (
79	    decision === PolicyDecision.ASK_USER &&
80	    toolCall.request.isClientInitiated
81	  ) {
82	    return {
83	      decision: PolicyDecision.ALLOW,
84	      rule: result.rule,
85	    };
86	  }
87	
88	  /*
89	   * Return the full check result including the rule that matched.
90	   * This is necessary to access metadata like custom deny messages.
91	   */
92	  if (decision === PolicyDecision.ASK_USER) {
93	    if (!config.isInteractive()) {
94	      throw new Error(
95	        `Tool execution for "${
96	          toolCall.tool.displayName || toolCall.tool.name
97	        }" requires user confirmation, which is not supported in non-interactive mode.`,
98	      );
99	    }
100	  }
101	
102	  return {
103	    decision,
104	    rule: result.rule,
105	  };
106	}
