112	export async function updatePolicy(
113	  tool: AnyDeclarativeTool,
114	  outcome: ToolConfirmationOutcome,
115	  confirmationDetails: SerializableConfirmationDetails | undefined,
116	  context: AgentLoopContext,
117	  messageBus: MessageBus,
118	  toolInvocation?: AnyToolInvocation,
119	): Promise<void> {
120	  // Mode Transitions (AUTO_EDIT)
121	  if (isAutoEditTransition(tool, outcome)) {
122	    context.config.setApprovalMode(ApprovalMode.AUTO_EDIT);
123	    return;
124	  }
125	
126	  // Determine persist scope if we are persisting.
127	  let persistScope: 'workspace' | 'user' | undefined;
128	  if (outcome === ToolConfirmationOutcome.ProceedAlwaysAndSave) {
129	    // If folder is trusted and workspace policies are enabled, we prefer workspace scope.
130	    if (
131	      context.config &&
132	      context.config.isTrustedFolder() &&
133	      context.config.getWorkspacePoliciesDir() !== undefined
134	    ) {
135	      persistScope = 'workspace';
136	    } else {
137	      persistScope = 'user';
138	    }
139	  }
140	
141	  // Specialized Tools (MCP)
142	  if (confirmationDetails?.type === 'mcp') {
143	    await handleMcpPolicyUpdate(
144	      tool,
145	      outcome,
146	      confirmationDetails,
147	      messageBus,
148	      persistScope,
149	    );
150	    return;
151	  }
152	
153	  // Generic Fallback (Shell, Info, etc.)
154	  await handleStandardPolicyUpdate(
155	    tool,
156	    outcome,
157	    confirmationDetails,
158	    messageBus,
159	    persistScope,
160	    toolInvocation,
161	    context.config,
162	  );
163	}
