/**
 * Registers policy rules for the browser agent's tools.
 *
 * When `confirmSensitiveActions` is enabled, sensitive tools (fill,
 * upload_file, evaluate_script) require explicit user confirmation. A rule for
 * `fill` is always registered; read-only tools are always allowed.
 *
 * @param config Runtime configuration (provides the shared PolicyEngine)
 * @param confirmSensitiveActions Whether sensitive actions require confirmation
 */
function registerBrowserAgentPolicyRules(
  config: Config,
  confirmSensitiveActions: boolean,
): void {
  const policyEngine = config.getPolicyEngine();
  if (!policyEngine) {
    return;
  }

  // Clear any rules registered by a prior invocation to avoid accumulation.
  policyEngine.removeRulesBySource(BROWSER_AGENT_POLICY_SOURCE);

  if (confirmSensitiveActions) {
    // Require user confirmation before sensitive actions.
    const sensitiveTools = ['fill', 'upload_file', 'evaluate_script'];
    for (const toolName of sensitiveTools) {
      policyEngine.addRule({
        toolName: qualifiedToolName(toolName),
        mcpName: BROWSER_AGENT_NAME,
        decision: PolicyDecision.ASK_USER,
        priority: 999,
        source: BROWSER_AGENT_POLICY_SOURCE,
      });
    }
